#!/usr/bin/env python3
"""Materialize root's scan-031 decisions after independent comparison."""
from pathlib import Path
from copy import deepcopy
import json
R=Path(__file__).resolve().parents[1]
raw={w:json.loads((R/f'readers/scan031/{w}/review.json').read_text()) for w in 'ABC'}
rows={w:raw[w]['loci'] for w in 'ABC'}
bmap={1:1,2:1,3:2,4:3,5:4,6:5,7:7,8:8,9:9,10:10}
cmap={1:1,2:None,3:2,4:3,5:4,6:5,7:6,8:7,9:8,10:9}
crops={1:'main/01_letterhead.png',2:'main/01_letterhead.png',3:'B/031_B_heading_A.png',4:'main/02_course_heading.png',5:'main/03_topic_heading.png',6:'B/031_B_icosaedre_overtyping.png',7:'main/04_dash.png',8:'B/031_B_group_A5.png',9:'B/031_B_right_pair.png',10:'B/031_B_archive_mark.png'}
loci=[]
for n,z in enumerate(rows['A'],1):
 x=deepcopy(z);x['id']=f'S031-{n:02}'
 x['readers']={'A':z['reading'],'B':rows['B'][bmap[n]-1]['reading'],'C':rows['C'][cmap[n]-1]['reading'] if cmap[n] else 'Uniform sans-serif block, as in witness C'}
 x['crop']='scan031/'+crops[n];x['decision']='Main crop inspection supports the stated reading.';x.pop('box',None);loci.append(x)
q={n:loci[n-1] for n in range(1,11)}
q[1].update(evidence='The main crop contains the full institutional text, two short rules, address, clear postal 34060 and the empty Montpellier, le prompt. H describes the letterhead in a note but omits these printed words and rules from its transcription. The typeface change is counted separately against C.',readers={w:'Full printed letterhead, two rules and blank date prompt transcribed' for w in 'ABC'})
q[2].update(evidence='Small terminal serifs are visible on the first two institutional lines. The institute/address/postal lines have the local sans-serif outlines. The final declaration preserves that within-block change.',readers={'A':'First two lines roman serif; following block sans serif','B':'First two lines roman serif; following block sans serif','C':'Uniform sans-serif block, as in witness C'},decision='Adopt A and B after root inspection of the header; no second H omission is counted for the same absent header.')
q[3].update(confidence='medium',evidence='The right diagonal and lower foot show an offset second edge beside the neighboring thin type. The main reader retains the doubled-letter encoding under the supplied typescript convention, with a detached point after the A.')
q[4]['evidence']='A continuous long rule lies about one typing line below the course heading and spans it from COURS through the final surname letter. Its distant placement is preserved.'
q[5]['evidence']='One continuous line lies directly beneath the whole topic phrase; the letters remain upright. The final text retains the close underline.'
q[6].update(reading=r"l'i\deleted{e}cosaèdre",diff_C=True,confidence='medium',unresolved=False,evidence='A fainter horizontal/sloping bar crosses the aperture of the live c, and a lighter lower return lies beneath it. These visible parts support the underlying e. The black live c remains clear.',decision='Resolve the C e doubt with reader B after root crop inspection; A and C retain the qualification.')
q[7]['evidence']='The separator between !) and ce is a single short rule in one typewriter cell. The final fragment preserves one hyphen.'
q[8].update(reading=r'$\handwritten{\unsure{\mathfrak A|\mathcal A}}_5$',diff_C=False,diff_H=True,confidence='medium',unresolved=True,evidence='The capital’s broad bowed left curve, folded top and angular internal return support frak A first. The round outer contour leaves cal A available. The low 5 has the separate regular typed form.',decision='Retain the alphabet qualification with B and C; A resolves frak A. The finite-group check does not select the alphabet.')
q[9]['evidence']='Two compact detached dark marks occupy the right margin below alterné and above the following baseline; the upper one is also farther right. Their actual pair and relative placement are drawn without assigning a verbal role.'
q[10].update(evidence='The dense irregular oblique shape has a broad lower-left body and a narrower raised upper-right end. White paper separates it from the border, beside pencilled archive 30. Its shape is drawn without a textual candidate or attribution.',decision='Preserve a geometric drawing as in A and B; C records it only in an archive comment. The archive numeral itself remains a comment.')
spacing=deepcopy(rows['B'][5]);spacing.update(id='S031-11',reading="l'ensemble``orienté''",C="l'ensemble ``orienté''",H='l\'ensemble "orienté"',crop='scan031/B/031_B_ensemble_quote.png',readers={'A':"l'ensemble ``orienté''",'B':"l'ensemble``orienté''",'C':"l'ensemble ``orienté''"},evidence='The final e, the double-quote cell and the first o occupy consecutive typewriter positions. The distance from e to o contains the quote cell alone, without an extra blank. The main crop confirms the adjacency.',decision='Adopt B’s spacing after root inspection; both witnesses and A/C supply a blank.',unresolved=False);spacing.pop('box',None);loci.append(spacing)
notes=(R/'decisions/scan031_notes.md').read_text()
rec={'scan':31,'loci':loci,'inventory':raw['B']['inventory'],'doubts':[{'location':q[8]['location'],'reading':r'\mathfrak A','alternatives':r'\mathcal A','confidence':'medium','reason':q[8]['evidence']}],'notes':notes,'check_events':[{'statement_id':'N031.1','date':'2026-11-20','who':'GPT-6 Astra Pro; effort not exposed; root/scan031','type':'carried as background without fault found','outcome':'Course programme and historical qualifications are reported from the page. The proposed geometric dictionary and the additional minimal-order claim are not independently proved.'},{'statement_id':'N031.3','date':'2026-11-20','who':'GPT-6 Astra Pro; effort not exposed; root/scan031','type':'computation or formal certificate','outcome':'Exhaustive Python enumeration of 60 even permutations, all products/inverses, five conjugacy classes and four full nonidentity normal closures, with an explicit noncommuting pair. Elementary proof interpretation establishes simplicity and noncommutativity. This is a computation, not a proof-assistant certificate; see scan031_math_checks.md.'}],'abbreviations':[{'abbr':a,'expansion':e,'scans':[31]} for a,e in [('C4','course designation C4'),('A.','initial of the author’s forename'),('CEDEX','courrier d’entreprise à distribution exceptionnelle')]],'consequential':['The handwritten group capital retains frak A / cal A; the low 5 is typed. The heading’s doubled A is preserved independently.','The faint underlying e is recovered under c. The typed space before the opening quote of orienté is removed after a character-pitch inspection.','Both omitted nonverbal shapes are drawn; the full printed letterhead, local typeface change and rule placements are retained.']}
(R/'decisions/scan031.json').write_text(json.dumps(rec,ensure_ascii=False,indent=2)+'\n')
page=(R/'readers/scan031/B/page.tex').read_text()
(R/'pages/J75-04_75_scan031.tex').write_text(page)
print(json.dumps({'loci':len(loci),'inventory':len(rec['inventory']),'doubts':len(rec['doubts']),'changes_C':sum(x['diff_C'] for x in loci),'changes_H':sum(x['diff_H'] for x in loci)}))
